        int c = s[i] - 'a';
        if (first[c] < 0) first[c] = i;
        last[c] = i;
    }
    int answer = 0;
    // A valid substring must start at the first occurrence of its first character.
    for (int c0 = 0; c0 < 26; c0++) {
        int left = first[c0];
