import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        int[] first = new int[26], last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] < 0) first[c] = i;
            last[c] = i;
        }
        int answer = 0;
        // A valid substring must start at the first occurrence of its first character.
        for (int c0 = 0; c0 < 26; c0++) {
            int left = first[c0];
            if (left < 0) continue;
            int end = left; // the furthest last occurrence of a character seen so far
            for (int right = left; right < n; right++) {
                int c = s.charAt(right) - 'a';
                if (first[c] < left) break;
                end = Math.max(end, last[c]);
                if (right >= end && right - left + 1 < n) answer = Math.max(answer, right - left + 1);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	n := len(s)
	var first, last [26]int
	for c := range first {
		first[c] = -1
	}
	for i, ch := range s {
		c := ch - 'a'
		if first[c] < 0 {
			first[c] = i
		}
		last[c] = i
	}
	answer := 0
	// A valid substring must start at the first occurrence of its first character.
	for _, left := range first {
		if left < 0 {
			continue
		}
		end := left // the furthest last occurrence of a character seen so far
		for right := left; right < n; right++ {
			c := s[right] - 'a'
			if first[c] < left {
				break
			}
			end = max(end, last[c])
			if right >= end && right-left+1 < n {
				answer = max(answer, right-left+1)
			}
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
